"""P5b: extremo externo, preview, exactitud, historia, snapshots y esquema futuro."""
import argparse,json,re
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
parser=argparse.ArgumentParser();parser.add_argument('--url',default='http://127.0.0.1:4178/');parser.add_argument('--seed',type=Path,default=Path('/tmp/p5b-seed'));parser.add_argument('--output',type=Path,default=Path('/tmp/p5b-browser'));args=parser.parse_args();args.output.mkdir(parents=True,exist_ok=True);errors=[];results=[]
instrument="""(()=>{const Native=Worker;window.__qaMainRuns=0;window.Worker=class extends Native{constructor(url,options){super(url,options);this.main=options?.name==='motor';}postMessage(m,t){if(this.main&&m.type==='run')window.__qaMainRuns++;return super.postMessage(m,t);}};})();"""
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage'])
 def fresh():
  page=browser.new_page(viewport={'width':1366,'height':768});page.add_init_script(instrument);page.on('pageerror',lambda e:(errors.append(str(e)),print('PAGEERROR',e)));page.goto(args.url);return page
 def open_file(page,path):page.locator('.shell-topbar input[type=file]').set_input_files(str(path));expect(page.get_by_text('Proyecto abierto',exact=True)).to_be_visible(timeout=60000);expect(page.get_by_test_id('engine-status')).to_contain_text('Listo',timeout=60000)
 def save(page,path):
  page.get_by_role('button',name='Proyecto',exact=True).click()
  with page.expect_download(timeout=60000) as download:page.get_by_role('menuitem',name=re.compile('^Guardar proyecto')).click()
  download.value.save_as(path);return json.loads(path.read_text())
 def editor(page):
  page.get_by_role('button',name='Preparar datos',exact=True).click();d=page.get_by_role('dialog',name='Preparar datos',exact=True);d.locator('summary',has_text='DRX · carga').click();d.get_by_role('combobox',name='Conjunto DRX',exact=True).select_option('lab');return d
 def compare(d):d.get_by_role('combobox',name='Curva para comparar con DRX',exact=True).select_option('gr');d.get_by_role('textbox',name='Máximo entre anclajes DRX (m)',exact=True).fill('1');d.get_by_role('button',name='Comparar con soporte declarado',exact=True).click();expect(d.get_by_role('table',name='Pares DRX',exact=False)).to_be_visible(timeout=60000)
 def setup(d,method):
  d.get_by_role('combobox',name='Zona de calibración GR',exact=True).select_option('z');d.get_by_role('combobox',name='Método Vsh a calibrar',exact=True).select_option(method)
  for label,value in [('Arcillas del extremo limpio (fracción de sólidos)','0'),('Arcillas del extremo lutítico (fracción de sólidos)','1'),('Relación constitutiva y alcance del proxy de Vsh','Proxy volumétrico sintético conocido, solo para Zona QA.'),('Referencia de laboratorio independiente del GR','Fixture Python independiente del motor, explícitamente sintético.')]:d.get_by_role('textbox',name=label,exact=True).fill(value)
  d.get_by_role('checkbox',name='Confirmo que el objetivo procede de laboratorio independiente, no de Vsh calculado con el mismo GR',exact=True).check()
 def external(d,end,value):
  d.get_by_role('combobox',name='Modo de ajuste GR',exact=True).select_option(end)
  for label,text in [('Valor GR externo fijo (gAPI)',value),('Referencia del extremo GR externo','Carta externa sintética independiente de este ajuste (QA).'),('Incertidumbre absoluta del extremo externo (gAPI, opcional)','1,5'),('Significado de la incertidumbre externa','Valor absoluto informado; no es una propagación ni intervalo de confianza.')]:d.get_by_role('textbox',name=label,exact=True).fill(text)
  d.get_by_role('checkbox',name='Declaro que el extremo fijo procede de evidencia externa aplicable a esta zona',exact=True).check()
 for method,end in [('linear','clean'),('linear','shale'),('clavier','clean')]:
  out=args.output/(method+'-'+end);out.mkdir(exist_ok=True);page=fresh();open_file(page,args.seed/(method+'-'+end+'.pozo.json'));before=save(page,out/'before.pozo.json');d=editor(page);compare(d);setup(d,method);propose=d.get_by_role('button',name='Proponer y previsualizar calibración GR',exact=True)
  baseline_runs=page.evaluate('__qaMainRuns');propose.click();apply=d.get_by_role('button',name='Aplicar calibración GR a esta zona',exact=True);expect(apply).to_be_disabled(timeout=60000);expect(d.get_by_text('Falta rango o soporte de ambos extremos.',exact=True)).to_be_visible();assert page.evaluate('__qaMainRuns')==baseline_runs
  value='25,0' if end=='clean' else '135,0';external(d,end,'25,25' if end=='clean' else '135,25');propose.click();expect(d.get_by_text('El extremo externo debe estar dentro del dominio y en el paso canónico; no se redondea ni recorta.',exact=False)).to_be_visible();expect(apply).to_have_count(0)
  d.get_by_role('textbox',name='Valor GR externo fijo (gAPI)',exact=True).fill(value);expect(propose).to_be_disabled();d.get_by_role('checkbox',name='Declaro que el extremo fijo procede de evidencia externa aplicable a esta zona',exact=True).check();propose.click();expect(apply).to_be_enabled(timeout=60000);assert page.evaluate('__qaMainRuns')==baseline_runs
  table=d.get_by_role('table',name='Extremos GR propuestos · gAPI',exact=True);expect(table).to_contain_text('externo fijo');expect(table).to_contain_text('25.0000');expect(table).to_contain_text('135.0000');table.screenshot(path=str(out/'fixed-preview.png'))
  d.get_by_role('textbox',name='Referencia del extremo GR externo',exact=True).fill('Referencia externa modificada durante la revisión.');expect(apply).to_have_count(0)
  external(d,end,value);propose.click();expect(apply).to_be_enabled(timeout=60000);apply.click();expect(page.get_by_test_id('engine-status')).to_contain_text('Listo',timeout=60000);d.get_by_role('button',name='Cerrar',exact=True).last.click();after=save(page,out/'applied.pozo.json')
  i=after['project']['wells'][0]['interpretation'];old=before['project']['wells'][0]['interpretation'];assert i['params']['zones']['z']=={**old['params']['zones']['z'],'grClean':25,'grShale':135,'vsh.method':method};assert i['params']['global']==old['params']['global'] and i['params']['zones']['other']==old['params']['zones']['other'] and i['sources']==old['sources'];assert after['project']['inputRevisions']==before['project']['inputRevisions'] and after['project']['blobs']==before['project']['blobs']
  key='xrd:gr-calibration:z';record=json.loads(i['pointSets']['lab']['settings'][key]);assert record['version']==record['config']['version']==2 and record['methodVersion']=='xrd-gr-fixed-v1';fixed=record['config']['fixed'];expected=25 if end=='clean' else 135;assert fixed['end']==end and fixed['value']==expected and fixed['externalDeclared'] and fixed['uncertainty']==1.5;assert record['fit']['raw'][end]==record['fit']['applied'][end]==expected and all(f['endpoints'][end]==expected for f in record['fit']['folds'])
  page.keyboard.press('Control+z');undone=save(page,out/'undo.pozo.json');assert undone['project']==before['project'];page.keyboard.press('Control+Shift+z');redone=save(page,out/'redo.pozo.json');assert redone['project']==after['project'];page.close()
  page=fresh();open_file(page,out/'applied.pozo.json');d=editor(page);d.locator('summary',has_text='Calibraciones GR aceptadas').click();expect(d.get_by_text('Carta externa sintética independiente',exact=False)).to_be_visible();expect(d.get_by_text('incertidumbre 1.5 gAPI',exact=False)).to_be_visible();d.get_by_role('button',name='Cerrar',exact=True).last.click()
  if method=='linear' and end=='clean':
   page.get_by_title('Snapshots',exact=True).click();snap=page.get_by_role('dialog',name='Snapshots',exact=True);snap.get_by_role('textbox',name='Nombre del snapshot',exact=True).fill('Extremo externo conocido');snap.get_by_role('button',name='Guardar snapshot',exact=True).click();page.keyboard.press('Escape');saved=save(page,out/'snapshot.pozo.json');modified=json.loads(json.dumps(saved));modified['project']['wells'][0]['interpretation']['params']['zones']['z']['grClean']=40;del modified['project']['wells'][0]['interpretation']['pointSets']['lab']['settings'][key];path=out/'changed.pozo.json';path.write_text(json.dumps(modified));open_file(page,path);page.get_by_title('Snapshots',exact=True).click();page.get_by_role('dialog',name='Snapshots',exact=True).get_by_role('button',name='Restaurar',exact=True).first.click();page.keyboard.press('Escape');restored=save(page,out/'restored.pozo.json');assert restored['project']['wells'][0]['interpretation']==i
   future=json.loads(json.dumps(saved));r={**record,'version':3};future['project']['wells'][0]['interpretation']['pointSets']['lab']['settings'][key]=json.dumps(r);path=out/'future.pozo.json';path.write_text(json.dumps(future));open_file(page,path);d=editor(page);d.locator('summary',has_text='Calibraciones GR aceptadas').click();expect(d.get_by_text('Versión de calibración GR desconocida; se conserva sin aplicar.',exact=False)).to_be_visible();d.get_by_role('button',name='Cerrar',exact=True).last.click();preserved=save(page,out/'future-preserved.pozo.json');assert json.loads(preserved['project']['wells'][0]['interpretation']['pointSets']['lab']['settings'][key])['version']==3
  results.append({'method':method,'fixed':end,'value':expected,'applied':[25,135],'version':2});page.close()
 assert not errors,errors
 (args.output/'result.json').write_text(json.dumps({'errors':errors,'cases':results,'checks':['both-extremes admission remains blocked','off-grid external value rejected','external declaration required','comma decimal entry','fixed unchanged raw applied folds','isolated preview no main run','reference change invalidates proposal','zonal application','originals cutoffs sources other zones intact','undo redo','reopen provenance','snapshot restores parameters and external reference','future record preserved']},indent=2));browser.close()
